import{_ as a,o as t,c as n,a2 as i}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"WeChat Channel Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/channels/weixin.md","filePath":"integrations/channels/weixin.md","lastUpdated":1790952322000}'),o={name:"integrations/channels/weixin.md"};function r(s,e,l,h,d,c){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="wechat-channel-configuration" tabindex="-1">WeChat Channel Configuration <a class="header-anchor" href="#wechat-channel-configuration" aria-label="Permalink to &quot;WeChat Channel Configuration&quot;">​</a></h1><p>Connect your Memoh bot to WeChat personal messaging: setup is a QR-code login, with no manual token or API key entry.</p><div class="warning custom-block"><p class="custom-block-title">Limits</p><ul><li>Private chats only.</li><li>Output is plain text; Markdown is not rendered.</li><li>Text messages are split into chunks of at most 4000 characters.</li><li>Responses are delivered as complete messages; output is not streamed.</li></ul></div><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>WeChat on your phone, signed in to the account the bot will use — you approve the login by scanning a QR code.</li></ul><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><h3 id="_1-add-the-wechat-channel-in-memoh" tabindex="-1">1. Add the WeChat channel in Memoh <a class="header-anchor" href="#_1-add-the-wechat-channel-in-memoh" aria-label="Permalink to &quot;1. Add the WeChat channel in Memoh&quot;">​</a></h3><p>In Memoh, open the bot&#39;s <strong>Platforms</strong> tab, click <strong>Add Channel</strong>, and select <strong>WeChat</strong>.</p><h3 id="_2-scan-the-qr-code" tabindex="-1">2. Scan the QR code <a class="header-anchor" href="#_2-scan-the-qr-code" aria-label="Permalink to &quot;2. Scan the QR code&quot;">​</a></h3><p>In Memoh:</p><ol><li>Click <strong>Start QR Login</strong>. Memoh fetches a QR code from the WeChat platform.</li><li>Open WeChat on your phone and scan the displayed QR code.</li><li>Confirm the login on your phone when prompted.</li></ol><p>Once confirmed, Memoh saves the credentials automatically and the channel is enabled.</p><h2 id="credentials" tabindex="-1">Credentials <a class="header-anchor" href="#credentials" aria-label="Permalink to &quot;Credentials&quot;">​</a></h2><p>QR login stores the session credentials automatically — there are no fields to fill in. One optional setting is available:</p><table tabindex="0"><thead><tr><th>Field</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><strong>Enable Typing</strong></td><td>No</td><td>Show a typing indicator while the bot generates a response.</td></tr></tbody></table><h2 id="verify" tabindex="-1">Verify <a class="header-anchor" href="#verify" aria-label="Permalink to &quot;Verify&quot;">​</a></h2><p>After the QR login succeeds, the channel is enabled automatically. Send <code>/help</code> to the bot in a WeChat private chat; the bot replies with its command list, which confirms the channel is working.</p><h2 id="disable-and-rotate-credentials" tabindex="-1">Disable and rotate credentials <a class="header-anchor" href="#disable-and-rotate-credentials" aria-label="Permalink to &quot;Disable and rotate credentials&quot;">​</a></h2><p>Disable or remove the channel at any time from the bot&#39;s <strong>Platforms</strong> tab. To sign in again, click <strong>Start QR Login</strong> and repeat the QR flow.</p><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ {#faq}&quot;">​</a></h2><h3 id="qr-expired" tabindex="-1">The QR code expired before I scanned it <a class="header-anchor" href="#qr-expired" aria-label="Permalink to &quot;The QR code expired before I scanned it {#qr-expired}&quot;">​</a></h3><p>The QR code is valid for a limited window. Click <strong>Start QR Login</strong> again to fetch a fresh one.</p>',22)])])}const m=a(o,[["render",r]]);export{u as __pageData,m as default};
